import { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { SingleImgStyle } from './index.style'
import CustomText from '../CustomText'
import { AgentColorPallette } from '../../configs/colorPallete'
import { ErrorCrossStyle } from '../../commonStyle/index.style'

class SingleImgContainer extends PureComponent {
  static propTypes = {
    imgUrl: PropTypes.string,
    titlePosition: PropTypes.string,
    title: PropTypes.string,
    height: PropTypes.string,
    imgClassName: PropTypes.string,
    titleAlign: PropTypes.string
  }

  getImgTitle = () => {
    const { title, titleAlign } = this.props
    return (
      <CustomText
        size='12px'
        color={AgentColorPallette.fontSecondary}
        top='4px'
        bottom='5px'
        textAlign={titleAlign || 'center'}
      >
        {title}
      </CustomText>
    )
  }

  render () {
    const { imgUrl, imgClassName, className, titlePosition, title, height, showVerified = false, minWidth } = this.props

    return (
      <SingleImgStyle className={className} height={height} minWidth={minWidth}>
        {
          titlePosition === 'up' && title && (
            this.getImgTitle()
          )
        }
        <div
          className={`single-img-box ${imgClassName}`}
          style={{
            backgroundImage: `url(${imgUrl})`
          }}
        />
        {
          titlePosition !== 'up' && title && (
            this.getImgTitle()
          )
        }
        {
          showVerified &&
            <ErrorCrossStyle right='0px' bg={AgentColorPallette.green}>
              <i className='fa fa-check' />
            </ErrorCrossStyle>
        }
      </SingleImgStyle>
    )
  }
}

export default SingleImgContainer
