import { useRef } from 'react'
import { CustomText } from '../../../../../components'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import AccessoriesWithImage from '../../../../Private/Application/components/AccessoriessWithImage'

function VehicleModificationData ({ policyData, hidePhotos, ...props }) {
  const errorAccessoryImages = {}
  const accessoriesRef = useRef()

  return (
    <CollapsibleCard
      title={LANG_STRINGS.vehicleModification}
      isOpen
      key='modificationData'
      className='offline-collapsible-card-wrapper'
    >
      {
        policyData.accessories?.length ? (
          <AccessoriesWithImage
            errorAccessoryImages={errorAccessoryImages}
            ref={accessoriesRef}
            accessories={policyData.accessories}
            name='policyOfflineAccessoriesData'
            className='offline-accessories-card'
            hidePhotos={hidePhotos}
            currencyLabel={policyData?.currency_label}
            currencySymbol={policyData?.currency_symbol}
            exchangeRate={policyData?.exchange_rate}
            {...props}
            isBtmBorder
          />
        )
          : (
            <CustomText color={AgentColorPallette.darkCharcoal} padLeft='12px'>
              {LANG_STRINGS.nothing}
            </CustomText>
          )
      }
    </CollapsibleCard>
  )
}

export default VehicleModificationData
