import { useCallback } from 'react'
import { Row, DisplayFlexCCC } from '../../commonStyle/index.style'
import { PHOTO } from '../../images'
import { LANG_STRINGS } from '../../lang'
import CollapsibleCard from '../CollapsibleCard'
import SingleImgContainer from '../SingleImgContainer'
import TitleError from '../TitleError'
import ZoomImg from '../zoomImg'
import { MVVehicleImgsStyle } from './index.style'

function MVVehicleImgs ({ title, titlePositionUp = true, images, className }) {
  const getNoImgContainer = useCallback((widthClass) => {
    return (
      <DisplayFlexCCC className={`no-img ${widthClass}`}>
        <img alt='dashboard-img' src={PHOTO} className='uploaded-image' />
      </DisplayFlexCCC>
    )
  }, [])

  const renderVehicleImg = useCallback(({ title, imgUrl, className, containerClass }) => {
    return (
      <div className={`img-container ${containerClass}`}>
        {titlePositionUp && <TitleError title={title} />}
        {
          imgUrl ? (
            <ZoomImg
              src={imgUrl}
              imgContainer={
                <SingleImgContainer
                  minWidth='0px'
                  imgUrl={imgUrl}
                  imgClassName={className}
                />
              }
            />
          ) : getNoImgContainer('img-width')
        }
        {
          !titlePositionUp && <TitleError title={title} />
        }
      </div>
    )
  }, [getNoImgContainer, titlePositionUp])

  const renderTwoContainerImg = useCallback(({
    leftData = {},
    rightData = {}
  }) => {
    return (
      <Row align='center'>
        {
          renderVehicleImg({
            ...leftData,
            className: 'padding-10',
            containerClass: ''
          })
        }
        {
          renderVehicleImg({
            ...rightData,
            className: 'padding-10',
            containerClass: ''
          })
        }
      </Row>
    )
  }, [renderVehicleImg])

  return (
    <CollapsibleCard
      title={title || LANG_STRINGS.vehiclePhoto}
      isOpen
      key='vehiclePhotoData'
      className={className}
    >
      <MVVehicleImgsStyle>
        {
          renderVehicleImg({
            imgUrl: images.dashboard,
            title: LANG_STRINGS.dashboard,
            className: 'width-100'
          })
        }
        <div className='separator' />
        {
          renderTwoContainerImg({
            leftData: {
              imgUrl: images.front,
              title: LANG_STRINGS.frontLook
            },
            rightData: {
              imgUrl: images.back,
              title: LANG_STRINGS.backView
            }
          })
        }
        <div className='separator' />
        {
          renderTwoContainerImg({
            leftData: {
              imgUrl: images.left,
              title: LANG_STRINGS.leftSide
            },
            rightData: {
              imgUrl: images.right,
              title: LANG_STRINGS.toTheRightSide
            }
          })
        }
      </MVVehicleImgsStyle>
    </CollapsibleCard>
  )
}

export default MVVehicleImgs
