import { useMemo, useState, useCallback } from 'react'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import BulkImgGalleryModal from '../../../../../components/Upload/UploadBulkImgModal/components/BulkImgGalleryModal'
import { LANG_STRINGS } from '../../../../../lang'
// import { NEW_POLICY_NEW_CAR, NEW_POLICY_USED_CAR } from '../../../../Private/Policy/constants'
import PolicyInfoRender from '../PolicyInfoRender'

function VehicleAttachmentData ({ isManualOrder, policyData = {} }) {
  const [galleryModal, setGalleryModal] = useState({
    showModal: false,
    images: []
  })

  const handleShowGalleryModal = useCallback((images) => {
    if (Array.isArray(images)) {
      setGalleryModal({
        showModal: true,
        label: LANG_STRINGS.gallery,
        images
      })
    }
  }, [])

  const handleCloseGalleryModal = useCallback(() => {
    setGalleryModal({
      showModal: false
    })
  }, [])

  const vehicleAttachment = useMemo(() => {
    let policyItems = []
    if (policyData.previous_certificate_url) {
      policyItems = [
        {
          title: LANG_STRINGS.copyOfPreviousPolicy,
          type: 'img',
          display: 'block',
          onClick: () => handleShowGalleryModal(policyData?.previous_certificate_url),
          value: policyData.previous_certificate_url
        }
      ]
    }
    return [
      ...policyItems,
      ...(policyData?.stnk_url ? [{
        title: LANG_STRINGS.stnkBstkPhoto,
        type: 'img',
        display: 'block',
        onClick: () => handleShowGalleryModal(policyData?.stnk_url),
        value: policyData?.stnk_url
      }] : []),
      ...(policyData?.appointment_letter_url
        ? [{
          title: LANG_STRINGS.letterOfAppointmentFromCustomer,
          type: 'img',
          display: 'block',
          onClick: () => handleShowGalleryModal(policyData?.appointment_letter_url),
          value: policyData?.appointment_letter_url
        }] : []
      ),
      ...(policyData?.vehicle_photos
        ? [{
          title: LANG_STRINGS.vehiclePhoto,
          type: 'img',
          display: 'block',
          onClick: () => handleShowGalleryModal(policyData?.vehicle_photos),
          value: policyData?.vehicle_photos
        }] : []
      ),
      {
        title: LANG_STRINGS.otherDocuments,
        type: policyData?.other_document_url && 'img',
        display: policyData?.other_document_url && 'block',
        onClick: () => handleShowGalleryModal(policyData?.other_document_url),
        value: policyData?.other_document_url || LANG_STRINGS.nothing
      },
      ...(policyData?.additional_info
        ? [{
          title: LANG_STRINGS.additionalInfo,
          display: 'block',
          value: policyData?.additional_info
        }] : []
      )
    ]
  }, [policyData, handleShowGalleryModal])

  return (
    <CollapsibleCard
      className='offline-collapsible-card-wrapper'
      title={LANG_STRINGS.attachment}
      isOpen
      key='vehicleAttachmentData'
    >
      <PolicyInfoRender
        data={vehicleAttachment}
      />
      {
        galleryModal.showModal && (
          <BulkImgGalleryModal
            show={galleryModal.showModal}
            onClose={handleCloseGalleryModal}
            uploadedImgs={galleryModal.images}
            title={galleryModal.label}
            hideDelete
          />
        )
      }
    </CollapsibleCard>
  )
}

export default VehicleAttachmentData
