import MVVehicleImgs from '../../../../../components/MVVehicleImgs'

function VehiclePhotoData ({ policyData }) {
  if (!policyData.images) return null
  return (
    <MVVehicleImgs
      images={policyData.images}
      className='offline-collapsible-card-wrapper'
    />
  )
}

export default VehiclePhotoData
