import { useMemo } from 'react'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { LANG_STRINGS } from '../../../../../lang'
import PolicyInfoRender from '../PolicyInfoRender'

function VehicleData ({ policyData = {} }) {
  const vehicleData = useMemo(() => ([
    {
      title: LANG_STRINGS.chassisNumber,
      value: policyData?.chasis_number
    },
    {
      title: LANG_STRINGS.machineNumber,
      value: policyData?.machine_number
    },
    {
      title: LANG_STRINGS.transmission,
      value: !policyData?.transmission_type ? '-' : (policyData?.transmission_type === 'Manual' ? policyData?.transmission_type : 'Otomatis')
    },
    {
      title: LANG_STRINGS.vehicleColor,
      value: policyData?.color
    }
  ]), [policyData])

  return (
    <CollapsibleCard
      className='offline-collapsible-card-wrapper'
      title={LANG_STRINGS.vehicleData}
      isOpen
      key='vehicleData'
    >
      <PolicyInfoRender
        data={vehicleData}
        name='vehicleDataRender'
      />
    </CollapsibleCard>
  )
}

export default VehicleData
