import { useCallback } from 'react'
import { CustomText } from '../../../../../components'
import PdfContainer from '../../../../../components/PdfContainer'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { PolicyInfoStyle } from './index.style'

function PolicyInfoRender ({ data = [], name, isBorder = true, isPadding = false, ...props }) {
  const renderTitleValues = useCallback((item) => {
    if (!Array.isArray(item.value) && item.type === 'img') {
      return (
        <PdfContainer url={item.value} />
      )
    } else if (Array.isArray(item.value) && item.type === 'img') {
      return (
        <CustomText color={AgentColorPallette.black} weight={600}>
          {item.value.length}&nbsp;&nbsp;
          <i className='fas fa-angle-right' />
        </CustomText>
      )
    } else {
      return (
        <CustomText
          className='break-word-newline'
          color={item.color || AgentColorPallette.darkCharcoal}
          weight={800}
        >
          {item.value || '-'}
        </CustomText>
      )
    }
  }, [])

  return (
    data.map((item, index) => (
      <PolicyInfoStyle
        isBorder={(index + 1) !== data.length && isBorder}
        isPadding={isPadding}
        align='center'
        display={!Array.isArray(item.value) && item.display}
        justify='space-between'
        onClick={item.onClick ? item.onClick : () => {}}
        key={`${name}-${index}`}
        bgColor={item.bgColor}
      >
        <CustomText color={AgentColorPallette.fontDarkerGrey}>
          {item.title}
        </CustomText>
        {renderTitleValues(item)}
      </PolicyInfoStyle>
    ))
  )
}

export default PolicyInfoRender
