import { Component } from 'react'
import PropTypes from 'prop-types'
import { AccessoriesImageStyle, AccessoriesRightSection } from './index.style'
import { DisplayFlexCCC, Row } from '../../../../../commonStyle/index.style'
import { CustomText, Upload } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { SEARCH } from '../../../../../images'
import { formatMoney, getConvertedCurrency } from '../../../../../helpers/utility'
import { ACCESSORY } from '../../../../../constants/quoatation'

class AccessoriesWithImage extends Component {
  static propTypes = {
    accessories: PropTypes.array,
    errorAccessoryImages: PropTypes.bool,
    isBtmBorder: PropTypes.bool,
    hidePhotos: PropTypes.bool,
    className: PropTypes.string,
    onZoomImg: PropTypes.func
  }

  constructor (props) {
    super(props)
    this.state = {
      imgUrl: '',
      error: '',
      isLoading: false,
      isOfflineDetails: props?.match?.params?.policyId,
      accessories: [
        ...props.accessories
      ],
      accessoryImgs: {}
    }
  }

  handleImagUpload = (imgData, index) => {
    const { accessories } = this.state
    const data = accessories[index]
    accessories[index] = {
      ...data,
      img: imgData[`accessory_${index}`]
    }
    this.setState({
      accessories
    })
  }

  handleZoomImgModal = (imgUrl, title, index, type) => {
    if (this.props.onZoomImg) {
      this.props.onZoomImg({
        imgUrl,
        title,
        index,
        type,
        onImgChange: this.handleImagUpload,
        onRemove: this.removeAccessoryImg
      })
    }
  }

  removeAccessoryImg = (data = {}) => {
    // here from the respected index we are removing
    // the img url
    const { index } = data
    const { accessories } = this.state
    accessories[index].img = ''
    this.setState({
      accessories
    })
  }

  getInputWithTitleContainer = (title, inputValue) => {
    return (
      <AccessoriesRightSection>
        <CustomText
          size='12px'
          color={AgentColorPallette.fontSecondary}
          top='4px'
          bottom='4px'
        >
          {title}
        </CustomText>
        <div className='accessories-value'>
          {inputValue}
        </div>
      </AccessoriesRightSection>
    )
  }

  calculatePrice = (amount) => {
    const { isOfflineDetails } = this.state
    const { currencyLabel = 'IDR', exchangeRate = 1, currencySymbol = 'Rp' } = this.props
    return (
      currencyLabel !== 'IDR' ? `${currencySymbol} ${!isOfflineDetails ? amount : getConvertedCurrency(amount, exchangeRate)}`
        : formatMoney(amount, 0, '')
    )
  }

  render () {
    const { accessories } = this.state
    return (
      <>
        {
          accessories.map((item, index) => (
            <AccessoriesImageStyle
              key={`accessory_${index}`}
              className={this.props.className}
              hidePhoto={this.props.hidePhotos}
              isBtmBorder={((index + 1) !== accessories.length) && this.props.isBtmBorder}
            >
              <Row>
                {
                  !this.props.hidePhotos && (
                    <div>
                      <CustomText
                        size='12px'
                        color={AgentColorPallette.fontSecondary}
                        top='4px'
                        bottom='4px'
                      >
                        {LANG_STRINGS.accessoriesPhoto}
                      </CustomText>
                      <div className='uploaded-image-container'>
                        {
                          item.img ? (
                            <DisplayFlexCCC className='accessory-img' onClick={() => this.handleZoomImgModal(item.img, item.name, index, 'accessory')}>
                              <img src={item.img} alt='' />
                              <div className='zoom-img'>
                                <img src={SEARCH} width='9px' alt='zoom' />
                              </div>
                            </DisplayFlexCCC>
                          )
                            : (
                              <Upload
                                onUpload={e => this.handleImagUpload(e, index)}
                                width='100%'
                                errorField={this.props.errorAccessoryImages && `accessory_${index}`}
                                name={`accessory_${index}`}
                                className='upload-doc-section'
                                invert
                              />
                            )
                        }
                      </div>
                    </div>
                  )
                }
                <div className='accessories-inputs'>
                  {this.getInputWithTitleContainer(LANG_STRINGS.accessoriesType, ACCESSORY[item.accessory_type])}
                  {this.getInputWithTitleContainer(LANG_STRINGS.accessoriesName, item.name)}
                  {this.getInputWithTitleContainer(LANG_STRINGS.accessoriesPrice, this.calculatePrice(item.sum_insured))}
                </div>
              </Row>
            </AccessoriesImageStyle>
          ))
        }
      </>
    )
  }
}

export default AccessoriesWithImage
